import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"VPS Cloud Disk User Guide","description":"","frontmatter":{"title":"VPS Cloud Disk User Guide"},"headers":[],"relativePath":"operations-knowledge-base/vps/vps-cloud-disk-user-guide.md","filePath":"operations-knowledge-base/vps/vps-cloud-disk-user-guide.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/vps/vps-cloud-disk-user-guide.md"};function n(r,t,l,d,h,c){return a(),i("div",null,[...t[0]||(t[0]=[o('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document describes the basic operations for VPS Cloud Disks, including creating, attaching, detaching, and deleting a cloud disk. It is intended to help customers quickly understand how to use the Cloud Disk feature.</p><p>A Cloud Disk provides additional storage space for your VPS and can be used to expand storage capacity, store business data, or manage data separately from the system disk.</p><p><strong>Applicable Product:</strong></p><ul><li>VPS (Virtual Private Server)</li></ul><hr><h2 id="_1-what-is-a-cloud-disk" tabindex="-1">1. What Is a Cloud Disk? <a class="header-anchor" href="#_1-what-is-a-cloud-disk" aria-label="Permalink to &quot;1. What Is a Cloud Disk?&quot;">​</a></h2><p>A Cloud Disk is an independent storage resource that can be attached to a VPS.</p><p>Unlike the system disk, a Cloud Disk is primarily used to store business data and can be attached, detached, or deleted as needed.</p><p><strong>Common use cases include:</strong></p><ul><li>Expanding server storage capacity</li><li>Storing website files</li><li>Storing database files</li><li>Separating business data from the operating system</li><li>Independent backup of business data</li></ul><hr><h2 id="_2-creating-a-cloud-disk" tabindex="-1">2. Creating a Cloud Disk <a class="header-anchor" href="#_2-creating-a-cloud-disk" aria-label="Permalink to &quot;2. Creating a Cloud Disk&quot;">​</a></h2><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Log in to the Raksmart Client Portal.</li><li>Go to <strong>Purchase Center → VPS</strong>.</li><li>Click <strong>Purchase Cloud Disk</strong>.</li><li>Select the desired disk capacity, region, and other configuration options based on your requirements.</li><li>Complete the payment. Once the order is completed, the Cloud Disk will appear in your account.</li></ol><p><strong>Note:</strong></p><p>When purchasing a Cloud Disk, make sure the selected <strong>region</strong> matches the VPS that you intend to attach it to. Otherwise, the Cloud Disk cannot be attached.</p><hr><h2 id="_3-attaching-a-cloud-disk" tabindex="-1">3. Attaching a Cloud Disk <a class="header-anchor" href="#_3-attaching-a-cloud-disk" aria-label="Permalink to &quot;3. Attaching a Cloud Disk&quot;">​</a></h2><h3 id="steps-1" tabindex="-1">Steps <a class="header-anchor" href="#steps-1" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Log in to the Raksmart Client Portal.</li><li>Go to <strong>Product Management → VPS → Cloud Disk</strong>.</li><li>Select the Cloud Disk you want to attach.</li><li>Click <strong>Mount</strong>.</li><li>Choose the target VPS from the instance list.</li><li>Confirm the operation to complete the attachment.</li></ol><p><strong>Notes:</strong></p><ul><li>A Cloud Disk can only be attached to a VPS located in the <strong>same region</strong>.</li><li>If the target VPS does not appear in the instance list, verify that it is located in the same region as the Cloud Disk.</li><li>Attaching a Cloud Disk <strong>does not reboot the VPS</strong> and <strong>does not interrupt running services</strong>.</li></ul><hr><h2 id="_4-what-should-i-do-after-attaching-the-cloud-disk" tabindex="-1">4. What Should I Do After Attaching the Cloud Disk? <a class="header-anchor" href="#_4-what-should-i-do-after-attaching-the-cloud-disk" aria-label="Permalink to &quot;4. What Should I Do After Attaching the Cloud Disk?&quot;">​</a></h2><p>After the Cloud Disk is attached through the control panel, the operating system will detect the new disk. However, the disk <strong>will not be automatically partitioned, formatted, or mounted</strong>.</p><p>You must log in to the server and complete the following steps according to your operating system:</p><ul><li>Detect the newly attached disk.</li><li>Create disk partitions (if required).</li><li>Create a file system (for first-time use).</li><li>Mount the disk to the desired directory.</li><li>Configure automatic mounting at system startup (if required).</li></ul><p><strong>Note:</strong></p><p>Completing the attachment in the control panel only connects the Cloud Disk to your VPS. The disk must still be initialized and mounted within the operating system before it can be used.</p><hr><h2 id="_5-detaching-a-cloud-disk" tabindex="-1">5. Detaching a Cloud Disk <a class="header-anchor" href="#_5-detaching-a-cloud-disk" aria-label="Permalink to &quot;5. Detaching a Cloud Disk&quot;">​</a></h2><p>If you need to remove a Cloud Disk from a VPS, you can detach it through the control panel.</p><h3 id="steps-2" tabindex="-1">Steps <a class="header-anchor" href="#steps-2" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Log in to the Raksmart Client Portal.</li><li>Go to <strong>Product Management → VPS → Cloud Disk</strong>.</li><li>Select the Cloud Disk.</li><li>Click <strong>Unmount</strong>.</li><li>Confirm that you want to detach the disk from the server.</li></ol><p><strong>Recommendation:</strong></p><p>Before detaching the Cloud Disk, unmount the file system from within the operating system and ensure that no applications or services are currently using the disk. This helps prevent data inconsistency or file system corruption.</p><p><strong>Note:</strong></p><p>Detaching a Cloud Disk <strong>does not delete the data stored on it</strong>.</p><hr><h2 id="_6-frequently-asked-questions" tabindex="-1">6. Frequently Asked Questions <a class="header-anchor" href="#_6-frequently-asked-questions" aria-label="Permalink to &quot;6. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-why-can-t-i-find-the-vps-that-i-want-to-attach-the-cloud-disk-to" tabindex="-1">Q1: Why can&#39;t I find the VPS that I want to attach the Cloud Disk to? <a class="header-anchor" href="#q1-why-can-t-i-find-the-vps-that-i-want-to-attach-the-cloud-disk-to" aria-label="Permalink to &quot;Q1: Why can&#39;t I find the VPS that I want to attach the Cloud Disk to?&quot;">​</a></h3><p>A Cloud Disk can only be attached to a VPS located in the <strong>same region</strong>.</p><p>If the target VPS does not appear in the instance list, please verify that both the Cloud Disk and the VPS are located in the same region.</p><hr><h3 id="q2-will-attaching-a-cloud-disk-reboot-my-vps" tabindex="-1">Q2: Will attaching a Cloud Disk reboot my VPS? <a class="header-anchor" href="#q2-will-attaching-a-cloud-disk-reboot-my-vps" aria-label="Permalink to &quot;Q2: Will attaching a Cloud Disk reboot my VPS?&quot;">​</a></h3><p>No.</p><p>Attaching a Cloud Disk through the control panel <strong>does not reboot the VPS</strong> and <strong>does not interrupt your running services</strong>.</p><hr><h3 id="q3-why-can-t-i-use-the-disk-immediately-after-attaching-it" tabindex="-1">Q3: Why can&#39;t I use the disk immediately after attaching it? <a class="header-anchor" href="#q3-why-can-t-i-use-the-disk-immediately-after-attaching-it" aria-label="Permalink to &quot;Q3: Why can&#39;t I use the disk immediately after attaching it?&quot;">​</a></h3><p>After the Cloud Disk is attached, you must initialize it within the operating system.</p><p>This includes:</p><ul><li>Creating partitions (if required)</li><li>Formatting the disk (first-time use)</li><li>Mounting the file system</li></ul><p>The Cloud Disk will be available for use only after these steps have been completed.</p><hr><h3 id="q4-will-detaching-a-cloud-disk-delete-my-data" tabindex="-1">Q4: Will detaching a Cloud Disk delete my data? <a class="header-anchor" href="#q4-will-detaching-a-cloud-disk-delete-my-data" aria-label="Permalink to &quot;Q4: Will detaching a Cloud Disk delete my data?&quot;">​</a></h3><p>No.</p><p>Detaching a Cloud Disk only removes the association between the disk and the VPS. The data stored on the Cloud Disk remains intact.</p><hr><h3 id="q5-can-i-recover-my-data-after-a-cloud-disk-has-been-reclaimed" tabindex="-1">Q5:Can I recover my data after a Cloud Disk has been reclaimed? <a class="header-anchor" href="#q5-can-i-recover-my-data-after-a-cloud-disk-has-been-reclaimed" aria-label="Permalink to &quot;Q5:Can I recover my data after a Cloud Disk has been reclaimed?&quot;">​</a></h3><p>No.</p><p>Once a Cloud Disk has been reclaimed due to expiration, cancellation, refund, or other service termination, the data stored on the disk cannot be recovered.</p><p>Please make sure to back up all important data before the Cloud Disk is reclaimed.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ A Cloud Disk can only be attached to a VPS in the <strong>same region</strong>. Cross-region attachment is not supported.</p><p>⚠️ After attaching a Cloud Disk, you must initialize and mount it within the operating system before it can be used.</p><p>⚠️ Attaching or detaching a Cloud Disk <strong>does not reboot the VPS</strong>.</p><p>⚠️If a Cloud Disk is reclaimed due to expiration, cancellation, refund, or other service termination, the data stored on the disk cannot be recovered. Please back up all important data in advance to avoid permanent data loss.</p><hr>',70)])])}const g=e(s,[["render",n]]);export{p as __pageData,g as default};
